#include <cstdint>
#include <vector>

struct Transport { int read(unsigned, unsigned char *, unsigned); };
struct Cache { void publish(const std::vector<unsigned char>&); };

void refresh(Transport& bus, Cache& cache)
{
    unsigned char header[4]{};
    if (bus.read(0, header, sizeof(header)) < 0) return;
    std::uint16_t length = static_cast<std::uint16_t>(header[2] | (header[3] << 8));
    std::vector<unsigned char> payload(length);
    if (bus.read(4, payload.data(), length) < 0) return;
    cache.publish(payload);
}
